using System.Text;using System.Text.Json;using Dapper;using Sigov.Application.Common;using Sigov.Application.Saude.Avancada;using Sigov.Infrastructure.Persistence.Dapper;
namespace Sigov.Infrastructure.Saude.Avancada;
public sealed class SaudeAvancadaRepository:ISaudeAcsOfflineRepository,ISaudeAcsSincronizacaoService,ISaudeAcsGeorreferenciaService,ISaudeAcsRelatorioService,ISaudeAcsCampoRepository,ISaudeDomicilioService,ISaudeVisitaDomiciliarService,ISaudeAtividadeColetivaService,ISaudeOcorrenciaCampoService,ISaudeOperacaoRepository,ISaudeVacinacaoAvancadaService,ISaudeFarmaciaAvancadaService,ISaudeRegulacaoAvancadaService,ISaudeOperacaoDashboardService,ISaudeRetaguardaRepository,ISaudeRetaguardaService,ISaudeEsusPreparatorioService,ISaudeSlaService,ISaudeSuporteService,ISaudeIndicadoresService
{
 static readonly HashSet<string> Recursos=new(StringComparer.Ordinal){"saude_acs_dispositivo","saude_acs_lote_offline","saude_acs_lote_item","saude_acs_sincronizacao","saude_acs_geoponto","saude_acs_inconsistencia","saude_domicilio","saude_cidadao_cadastro_individual","saude_visita_domiciliar","saude_atividade_coletiva","saude_consumo_alimentar_marcador","saude_ocorrencia_campo","saude_denuncia_dengue","saude_vacina_calendario","saude_vacinacao_evento","saude_farmacia_estoque","saude_farmacia_lote","saude_farmacia_dispensacao","saude_farmacia_alerta","saude_regulacao_fila","saude_regulacao_movimento","saude_retaguarda_indicador","saude_retaguarda_producao_acs","saude_retaguarda_mapa_ponto","saude_esus_lote_preparatorio","saude_esus_inconsistencia","saude_sla_metrica","saude_suporte_chamado","saude_suporte_mensagem","saude_suporte_satisfacao"};
 readonly DapperContext _context;public SaudeAvancadaRepository(DapperContext context)=>_context=context;
 public async Task<PagedResult<SaudeAvancadaRegistroDto>> ListarAsync(long tenantId,string recurso,SaudeAvancadaFiltro f,CancellationToken ct){recurso=Recurso(recurso);var p=Math.Max(1,f.Pagina);var t=Math.Clamp(f.Tamanho,1,100);var sql=$"select id as Id,codigo as Codigo,tipo as Tipo,status as Status,descricao as Descricao,gravidade as Gravidade,latitude as Latitude,longitude as Longitude,quantidade as Quantidade,created_at as CreatedAt from sigov.{recurso} where tenant_id=@TenantId and is_deleted=false and (@Status is null or status=@Status) and (@Tipo is null or tipo=@Tipo) and (@UnidadeSaudeId is null or unidade_saude_id=@UnidadeSaudeId) and (@PacienteId is null or paciente_id=@PacienteId) order by id desc limit @Tamanho offset @Offset;select count(1) from sigov.{recurso} where tenant_id=@TenantId and is_deleted=false and (@Status is null or status=@Status) and (@Tipo is null or tipo=@Tipo)";using var c=_context.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,new{TenantId=tenantId,f.Status,f.Tipo,f.UnidadeSaudeId,f.PacienteId,Tamanho=t,Offset=(p-1)*t},cancellationToken:ct));var rows=(await m.ReadAsync<SaudeAvancadaRegistroDto>()).ToList();return new(rows,p,t,await m.ReadSingleAsync<long>());}
 public async Task<SaudeAvancadaRegistroDto?> ObterAsync(long tenantId,string recurso,long id,CancellationToken ct){recurso=Recurso(recurso);using var c=_context.CreateConnection();return await c.QuerySingleOrDefaultAsync<SaudeAvancadaRegistroDto>(new CommandDefinition($"select id as Id,codigo as Codigo,tipo as Tipo,status as Status,descricao as Descricao,gravidade as Gravidade,latitude as Latitude,longitude as Longitude,quantidade as Quantidade,created_at as CreatedAt from sigov.{recurso} where tenant_id=@TenantId and id=@Id and is_deleted=false",new{TenantId=tenantId,Id=id},cancellationToken:ct));}
 public async Task<long> CriarAsync(SaudeAvancadaContext x,string recurso,SaudeAvancadaOperacaoRequest r,CancellationToken ct){recurso=Recurso(recurso);Validar(recurso,r);using var c=_context.CreateConnection();var sql=$"insert into sigov.{recurso}(tenant_id,entidade_id,exercicio_id,unidade_saude_id,paciente_id,profissional_id,acs_id,domicilio_id,referencia_id,lote_id,dispositivo_id,codigo,chave_offline,origem,tipo,status,gravidade,descricao,justificativa,latitude,longitude,quantidade,saldo_minimo,data_referencia,validade,dados,auditoria,correlation_id,created_by) values(@TenantId,@EntidadeId,@ExercicioId,@UnidadeSaudeId,@PacienteId,@ProfissionalId,@AcsId,@DomicilioId,@ReferenciaId,@LoteId,@DispositivoId,@Codigo,@ChaveOffline,@Origem,@Tipo,@Status,@Gravidade,@Descricao,@Justificativa,@Latitude,@Longitude,@Quantidade,@SaldoMinimo,@DataReferencia,@Validade,@Dados::jsonb,jsonb_build_object('acao','CRIAR','em',now()),@CorrelationId,@UsuarioId) returning id";return await c.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{x.TenantId,x.EntidadeId,x.ExercicioId,r.UnidadeSaudeId,r.PacienteId,r.ProfissionalId,r.AcsId,r.DomicilioId,r.ReferenciaId,r.LoteId,r.DispositivoId,r.Codigo,r.ChaveOffline,r.Origem,r.Tipo,r.Status,r.Gravidade,r.Descricao,r.Justificativa,r.Latitude,r.Longitude,r.Quantidade,r.SaldoMinimo,r.DataReferencia,r.Validade,Dados=JsonSerializer.Serialize(r.Dados??new Dictionary<string,object?>()),CorrelationId=Guid.TryParse(x.CorrelationId,out var g)?g:Guid.NewGuid(),x.UsuarioId},cancellationToken:ct));}
 public async Task<bool> AlterarStatusAsync(SaudeAvancadaContext x,string recurso,long id,string status,string? justificativa,CancellationToken ct){recurso=Recurso(recurso);if ((status is "CANCELADO" or "CANCELADA" or "RECUSADA") && string.IsNullOrWhiteSpace(justificativa))throw new ArgumentException("Cancelamento ou recusa exige justificativa.");using var c=_context.CreateConnection();return await c.ExecuteAsync(new CommandDefinition($"update sigov.{recurso} set status=@Status,justificativa=coalesce(@Justificativa,justificativa),updated_at=now(),updated_by=@UsuarioId,correlation_id=@CorrelationId,auditoria=auditoria||jsonb_build_object('acao','STATUS','status',@Status,'em',now()) where tenant_id=@TenantId and id=@Id and is_deleted=false",new{x.TenantId,Id=id,Status=status,Justificativa=justificativa,x.UsuarioId,CorrelationId=Guid.TryParse(x.CorrelationId,out var g)?g:Guid.NewGuid()},cancellationToken:ct))>0;}
 public async Task<SaudeAvancadaDashboardDto> DashboardAsync(long tenantId,string recurso,CancellationToken ct){var page=await ListarAsync(tenantId,recurso,new SaudeAvancadaFiltro(Tamanho:8),ct);return new(page.TotalCount,page.Items.LongCount(x=>x.Status.Contains("AGUARDANDO",StringComparison.Ordinal)||x.Status=="RASCUNHO"),page.Items.LongCount(x=>x.Gravidade=="ALTA"||x.Status=="COM_INCONSISTENCIA"),page.Items.LongCount(x=>x.Latitude.HasValue&&x.Longitude.HasValue),page.Items);}
 public async Task<byte[]> ExportarCsvAsync(long tenantId,string recurso,CancellationToken ct){var p=await ListarAsync(tenantId,recurso,new SaudeAvancadaFiltro(Tamanho:100),ct);var b=new StringBuilder("id;codigo;tipo;status;gravidade;criado_em\n");foreach(var x in p.Items)b.Append(x.Id).Append(';').Append(Limpar(x.Codigo)).Append(';').Append(Limpar(x.Tipo)).Append(';').Append(x.Status).Append(';').Append(x.Gravidade).Append(';').Append(x.CreatedAt).Append('\n');return Encoding.UTF8.GetBytes(b.ToString());}
 static void Validar(string recurso,SaudeAvancadaOperacaoRequest r){if(string.IsNullOrWhiteSpace(r.Status)||string.IsNullOrWhiteSpace(r.Origem))throw new ArgumentException("Status e origem são obrigatórios.");if((r.Latitude.HasValue&&!r.Longitude.HasValue)||(!r.Latitude.HasValue&&r.Longitude.HasValue))throw new ArgumentException("Latitude e longitude devem ser informadas juntas.");if(recurso=="saude_acs_dispositivo"&&(!r.AcsId.HasValue||string.IsNullOrWhiteSpace(r.Codigo)))throw new ArgumentException("Dispositivo exige ACS e identificação.");if(recurso=="saude_acs_lote_offline"&&(!r.AcsId.HasValue||!r.DispositivoId.HasValue||!r.DataReferencia.HasValue))throw new ArgumentException("Lote offline exige ACS, dispositivo e data de coleta.");if(recurso=="saude_visita_domiciliar"&&(!r.AcsId.HasValue||(!r.DomicilioId.HasValue&&!r.PacienteId.HasValue)||!r.DataReferencia.HasValue||string.IsNullOrWhiteSpace(r.Tipo)))throw new ArgumentException("Visita exige ACS, domicílio ou cidadão, data e motivo.");if(recurso=="saude_farmacia_dispensacao"&&(!r.PacienteId.HasValue||r.Quantidade<=0))throw new ArgumentException("Dispensação exige paciente e quantidade positiva.");if(recurso=="saude_vacinacao_evento"&&(!r.PacienteId.HasValue||!r.ProfissionalId.HasValue||!r.DataReferencia.HasValue))throw new ArgumentException("Aplicação exige paciente, profissional e data.");}
 static string Recurso(string r)=>Recursos.Contains(r)?r:throw new ArgumentException("Recurso de Saúde Avançada inválido.");static string Limpar(string? s)=>(s??string.Empty).Replace(";",string.Empty,StringComparison.Ordinal).Replace("\n"," ",StringComparison.Ordinal);
}
